entries[230184] = { ["name"] = "Chaos-Forged Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Born and raised during a time of great chaos, this mount has survived hardships known by few.\"\nIn-Game Shop" }
entries[230185] = { ["name"] = "Chaos-Forged Hippogryph", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Born and raised during a time of great chaos, this mount has survived hardships known by few.\"\nIn-Game Shop" }
entries[230186] = { ["name"] = "Mister Pick-Me-Up", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 Intellect\nEquip: Your healing spells and abilities have a chance to summon Mister Pick-Me-Up for 6 sec, firing a healing beam every 2 sec that jumps between 5 injured allies to restore 55137 health each.\n\nOverhealing from this effect irradiates allies to deal Nature damage to nearby enemies over 1.5 sec, increased by additional overhealing.\nDefeat Sprocketmonger Lockenstock in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230188] = { ["name"] = "Gallagio Bottle Service", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,341 Haste\nUse: Become the pinnacle of Gallagio service excellence and dole out Kaja'Cola Mega-Lite to injured allies 10 times over 4 sec, healing them for 789757 and increasing their Speed by 1407 for 5 sec. The number of servings is increased by your Haste. (1 Min, 30 Sec Cooldown)\nDefeat One-Armed Bandit in Liberation of Undermine on Mythic difficulty.\n\"Contains 0.01% kaja'mite.\"\nSell Price:" }
entries[230189] = { ["name"] = "Junkmaestro's Mega Magnet", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 Agility\nEquip: Your damaging abilities have a very high chance to charge the magnet, up to 30 times.\nUse: Reverse the magnet's polarity to violently recycle buried garbage, dealing ( 71728 * 1 ) Plague damage to your target per charge. Lingering virulence deals 10% of the damage dealt to 5 nearby enemies over 6 sec. (20 Sec Cooldown)\nDefeat Stix Bunkjunker in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230190] = { ["name"] = "Torq's Big Red Button", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,341 Mastery\nUse: Unleash your inner tempest to gain 6712 Strength for 15 sec. Your next 3 abilities cause a lightning blast dealing ( 359475 * 1 ) Nature damage to your primary target. Damage increased by 100% with each subsequent blast. (2 Min Cooldown)\nDefeat Cauldron of Carnage in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230191] = { ["name"] = "Flarendo's Pilot Light", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,341 Haste\nUse: Reignite the pilot light to gain 6712 Intellect for 15 sec. After casting 3 harmful spells, it unleashes a beam dealing ( 1997082 * 1 ) Fire damage to your primary target and ( 1997082 * 8 / 100 * 1 ) damage to up to 5 enemies in its path. (2 Min Cooldown)\nDefeat Cauldron of Carnage in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230192] = { ["name"] = "Mug's Moxie Jug", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 Intellect\nEquip: Your spells have a chance to send you into a frenzy, granting you 668 Critical Strike for 15 sec. While frenzied, each spell cast grants an additional 668 Critical Strike but does not refresh the duration. This effect may only occur every 1 sec.\nDefeat Mug'Zee in Liberation of Undermine on Mythic difficulty.\n\"The word 'Moxie' is hastily scribbled on.\"\nSell Price:" }
entries[230193] = { ["name"] = "Mister Lock-N-Stalk", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,341 Haste\nEquip: Your spells and abilities have a high chance to lase your target for Precision Blasting , calling in Mister Lock-N-Stalk to deal ( 790399 * 1 ) Physical damage to your target. (3s cooldown)\nUse: Recalibrate for Mass Destruction . (20 Sec Cooldown)\nDefeat Sprocketmonger Lockenstock in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230194] = { ["name"] = "Reverb Radio", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a high chance to Hype you up, granting 314 Haste up to 5 times. Upon reaching maximum Hype, amp it up by 100% for 15 sec before starting again.\nDefeat Rik Reverb in Liberation of Undermine on Mythic difficulty.\n\"Rik & Roll, baby!\"\nSell Price:" }
entries[230196] = { ["name"] = "11.0 Raid Template - Ranged DPS - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Intellect]\nSell Price:" }
entries[230197] = { ["name"] = "Geargrinder's Spare Keys", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength or Intellect]\nUse: Launch a Geargrinder trike to its final blaze of glory, exploding upon impacting the first enemy in its path to deal ( 1 * 1584503 ) Fire damage split between all nearby enemies. (2 Min Cooldown)\nDefeat Vexie in Liberation of Undermine on Mythic difficulty.\n\"I'm gonna step on the gas!\"\nSell Price:" }
entries[230198] = { ["name"] = "Eye of Kezan", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,341 Mastery\nEquip: Your spells and abilities have a high chance to empower the Eye and grant you 243 Primary Stat up to 20 times, decaying rapidly upon leaving combat. While fully empowered, the Eye instead deals ( 64528 * 1 ) Fire damage to enemies or heals allies for 96796 .\nDefeat Gallywix in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230199] = { ["name"] = "Zee's Thug Hotline", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength]\nEquip: Your abilities have a chance to call a member of the Goon Squad to attack your target for 10 sec. Gaining Bloodlust or a similar effect summons the whole crew.\nDefeat Mug'Zee in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
