entries[230724] = { ["name"] = "Astral Jeweler's Setting", ["text"] = "Binds when picked up\nUse: Add 1 [socket][sockets] to a War Within PvP item. Can be used on Helms, Amulets, Bracers, Belts, and Rings.\n[\nJewelry can have up to 2 sockets.]\n\nMust be used during The War Within Season 3.\nSell Price:" }
