entries[230728] = { ["name"] = "Experimental Go-Pack", ["text"] = "Binds when picked up\nUnique (10)\nUse: Equip the Go-Pack and propel yourself upwards into the air. Usable for repeated jumps only on the Siren Island. (10 Sec Cooldown)\n\"It has two speeds. \"What a view\" and \"Oh no, not again!\"\"\nSell Price:" }
entries[230729] = { ["name"] = "Appropriated Azerothian Camera", ["text"] = "Quest Item\nUse: Stand still to document nearby flora and fauna. (3 Sec Cooldown)\n\"Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.\"" }
