entries[231022] = { ["name"] = "Bits o' Scrap", ["text"] = "Quest Item\n\"Useful bits of goblin scrap metal from all sorts of goblin-made machinery.\"" }
entries[231064] = { ["name"] = "Throwaway Gangster Disguise", ["text"] = "Binds when picked up\nToy\nUse: Disguise yourself as a certified Undermine gangster, fooling the locals into leaving you alone for 20 min. Only usable in Undermine. (1 Hour Cooldown)" }
entries[231089] = { ["name"] = "Correspondence from Zirdo", ["text"] = "Quest Item\nUnique\n\"A letter from Zirdo detailing Pamsy's involvement in opening the wall, attracting attention to Gallywix's Black Blood mining. This will prove Zirdo snitched on Pamsy, causing Gozzic to attack her engineers.\"" }
entries[231099] = { ["name"] = "Back-Strapped Missile", ["text"] = "Binds when picked up\nUse: Instructions\nStep 1: Latch missile to back.\nStep 2: Ignite Missile.\nStep 3: Go up.\n\nOnly usable in Undermine. (1 Min Cooldown)\nSell Price:" }
entries[231116] = { ["name"] = "Cursed Pirate Skull", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+2,753 [Agility or Strength]\n+ 565 Leech\nEquip: Your melee attacks have a chance of stirring a nova of blood that deals 15514 Shadow damage to 5 enemies within 5 yd of you every sec for 8 sec.\nSell Price:" }
entries[231117] = { ["name"] = "Darktide Wavebender's Orb", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+2,753 [Agility or Intellect]\nEquip: Your ranged spells and abilities have a chance to launch a glob of water at an enemy dealing 76721 Frost damage to them and 4 other enemies within 7 yd of them.\nSell Price:" }
entries[231118] = { ["name"] = "Runecaster's Stormbound Rune", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+2,753 [Agility or Strength or Intellect]\nEquip: Every 6 sec spent in combat causes the rune to overcharge, striking a nearby enemy with lightning dealing 55239 Nature damage.\n\nThis effect triggers immediately when striking a creature for the first time.\nSell Price:" }
