entries[231163] = { ["name"] = "Appropriated Azerothian Camera", ["text"] = "Quest Item\nUse: Stand still to document nearby flora and fauna. (3 Sec Cooldown)\n\"Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.\"" }
entries[231164] = { ["name"] = "Goblin Grapnel", ["text"] = "Quest Item\nUse: Toss the grappling hook at a Scrap Harvester within 40 yards, pulling it towards you. (5 Sec Cooldown)\n\"Get flying robots to fall for you, hook, line, and sinker.\"" }
entries[231173] = { ["name"] = "Junkmaestro's Magnetomech", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Well-suited for compacting trash into rollable balls. Junkmaestro apocrypha claims these might become worlds of their own if only they could get big enough.\"\nAchievement:\nGlory of the Liberation of Undermine Raider\nCategory:\nDungeons & Raids" }
entries[231263] = { ["name"] = "The Case of the Superstitious and Hungry Pirates", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"Notes detailing my adventures helping the stranded Booty Bay Buccaneers in their time of need.\"\n<Right Click to Read>" }
entries[231264] = { ["name"] = "Glorious Cluster of Gilded Undermine Crests", ["text"] = "Binds when picked up\nUse: Collect 15 Gilded Undermine Crests.\nYou cannot earn 15 Gilded Undermine Crests right now." }
entries[231265] = { ["name"] = "The Jastor Diamond", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+10,948 Stamina\n+ 826 Haste\n+ 4,626 Mastery\nEquip: Take Credit for your allies' deeds up to once every 12 sec, gaining 66 of their highest secondary stat up to 10 times until shortly after leaving combat. You have a 10% chance to get caught in the act, transferring all accumulated Credit to your ally for 15 sec instead.\nDefeat Gallywix in Liberation of Undermine on Mythic difficulty.\n\"I'm not gonna give you a detailed receipt of all the businesses I took over, started, sold, or destroyed. I won: that's all. I won everything I wanted.\"\nSell Price:" }
entries[231266] = { ["name"] = "Random Number Perforator", ["text"] = "Binds when picked up\nOne-Hand Dagger\n2,508 - 4,180 Damage Speed 1.80\n(1,858 damage per second)\n+1,634 Agility\n+9,732 Stamina\n+ 620 Critical Strike\n+ 318 Mastery\nDurability 80 / 80\nDefeat One-Armed Bandit in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[231267] = { ["name"] = "Pouch of Weathered Undermine Crests", ["text"] = "Binds when picked up\nUse: Collect 15 Weathered Undermine Crests. These Crests ignore the seasonal cap.\nComplete the quest \"Don't Undermine the Crests\" from Vaskarn in Dornogal to be able to downgrade your Undermine Crests." }
entries[231268] = { ["name"] = "Blastfurious Machete", ["text"] = "Binds when picked up\nOne-Hand Sword\n1,811 - 3,019 Damage Speed 2.60\n(928.8 damage per second)\n+9,519 Intellect\n+9,732 Stamina\n+ 611 Critical Strike\n+ 327 Haste\nDurability 110 / 110\nDefeat Vexie in Liberation of Undermine on Mythic difficulty.\n\"The word 'Family' is etched into its hilt.\"\nSell Price:" }
entries[231269] = { ["name"] = "Satchel of Carved Undermine Crests", ["text"] = "Binds when picked up\nUse: Collect 15 Carved Undermine Crests. These Crests ignore the seasonal cap.\nComplete the quest \"Don't Undermine the Crests\" from Vaskarn in Dornogal to be able to downgrade your Undermine Crests." }
