entries[231757] = { ["name"] = "Fractured Spark of Starlight", ["text"] = "The War Within Season 3\nBinds when picked up\nUse: Combine 2 Fractured Sparks of Starlight with 250 Valorstones to create a Spark of Starlight.\nCrafting Reagent\n\"A fragment of a Spark of Starlight that can be reformed if combined with another piece. Primarily obtained through weekly caches.\"\nSell Price:" }
