entries[231773] = { ["name"] = "Lost & Found Chest", ["text"] = "Quest Item\nUse: Unpack the chest to get all five of the items out of it.\n\"Chest containing lost-and-found items Alyx needs delivered to their correct owners.\"" }
entries[231786] = { ["name"] = "Ookler's Diary", ["text"] = "Quest Item\n\"Disjointed scribbles that document one Hozen's five whimsical visits to the island.\"" }
entries[231788] = { ["name"] = "Songs of the Siren", ["text"] = "Quest Item\n\"Twenty-two pages filled with the same repeating, indecipherable words.\"" }
entries[231791] = { ["name"] = "Redeemer's Sigil", ["text"] = "Quest Item\nUnique\nUse: Raise the Redeemer's Sigil aloft to drive away the shadow's corruption.\n\"Old, but immaculately kept.\"" }
entries[231802] = { ["name"] = "Ashvane Co. Survey Report", ["text"] = "Quest Item\n\"Records the reckless greed that led Ashvane Co. to ignore safety concerns.\"" }
entries[231804] = { ["name"] = "Game Piece", ["text"] = "Quest Item\n\"An assorted collection of game pieces.\"" }
entries[231808] = { ["name"] = "Ancient Treasure Notes", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"The notes have very sloppy handwriting and don't look all that ancient.\"\n<Right Click to Read>" }
entries[231809] = { ["name"] = "First Mate Dat-Dat's Key", ["text"] = "Binds when picked up\n\"Key to Dat-Dat's private stash of reading material.\"\nSell Price:" }
entries[231810] = { ["name"] = "Alyx's Lost & Found Notes", ["text"] = "Secrets of Azeroth\nQuest Item\n\"I took down as much information as I could, but everyone was talking so fast and all at once so this might be a little disjointed.\"\n<Right Click to Read>" }
entries[231812] = { ["name"] = "Hozen Poetry", ["text"] = "Quest Item\n\"Includes poems \"Happy Tails\", \"Ookie Eats Rats\" and \"The Dark Abyss\"\"" }
entries[231813] = { ["name"] = "Siren Isle Manifest", ["text"] = "Quest Item\n\"Numerous efforts to unfairly divide the spoils plundered from the island.\"" }
