entries[231821] = { ["name"] = "Makeshift Explosives", ["text"] = "Quest Item\nUse: Stuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 2 sec.\nInflicts 4 Fire damage to enemies within 5 yards of the impact. (5 Sec Cooldown)\n\"These makeshift explosive should do the trick. An explosion is an explosion after all.\"" }
