entries[231878] = { ["name"] = "Articles of Proof", ["text"] = "Quest Item\n\"These assorted items belong to the various human factions that make up the Red Dawn.\"" }
entries[231879] = { ["name"] = "Defias Bandana", ["text"] = "Quest Item\n\"Article of Proof. The signature red bandana worn by the Defias Brotherhood. Old and faded but still vibrant.\"" }
entries[231880] = { ["name"] = "Orange Bandana", ["text"] = "Quest Item\n\"Article of Proof. This orange bandana, frequently worn by those affiliated with the Syndicate, stands out against the red of Stromgarde, the Defias, and the Scarlet Crusade.\"" }
entries[231881] = { ["name"] = "Syndicate Emblem", ["text"] = "Quest Item\n\"Article of Proof. You've heard rogues used to pickpocket these, but it's much easier to loot off a dead body.\"" }
entries[231883] = { ["name"] = "Scarlet Crusade Tabard", ["text"] = "Quest Item\n\"Article of Proof. This tabard doesn't seem as rare as others have made it out to be.\"" }
entries[231884] = { ["name"] = "Stromgarde Tabard", ["text"] = "Quest Item\n\"Article of Proof. A tabard worn by soldiers of Stromgarde. Old and tattered, it has not been well cared for.\"" }
entries[231886] = { ["name"] = "Mildewed Celebration Crate", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique\nThis Item Begins a Quest" }
entries[231888] = { ["name"] = "Mildewed Ransom Note", ["text"] = "Secrets of Azeroth\nBinds when picked up\n<Right Click to Read>" }
entries[231889] = { ["name"] = "New-To-You Mechanical Parts", ["text"] = "Quest Item\n\"Serviceable parts, if you don't mind a few blemishes and the smell of gunpowder. Adds character, right?\"" }
entries[231893] = { ["name"] = "Grease Residue", ["text"] = "Quest Item\n\"Leftovers from the Underriders. Good for something!\"" }
entries[231894] = { ["name"] = "Useful Trash", ["text"] = "Quest Item" }
entries[231895] = { ["name"] = "Leftover Mocktail", ["text"] = "Quest Item\n\"Still has the little umbrella in it!\"" }
entries[231897] = { ["name"] = "Rusted Coin", ["text"] = "Quest Item\n\"Has no monetary value. But is useful for chemical reactions.\"" }
entries[231898] = { ["name"] = "Industrial-Grade Makeup Remover", ["text"] = "Quest Item\n\"Powerful stuff. Can dissolve through the bottom of a garbage can.\"" }
entries[231899] = { ["name"] = "Trash", ["text"] = "\"It's just trash.\"\nSell Price:" }
entries[231900] = { ["name"] = "Sample Potion", ["text"] = "Quest Item\nUse: Toss a sample! (4 Sec Cooldown)\n\"Free sample! Ready to be tossed at a Potential Customer!\"" }
entries[231905] = { ["name"] = "Letters", ["text"] = "Secrets of Azeroth\nQuest Item\nUse: Distribute the letters to visitors outside of the Caverns of Time. (3 Sec Cooldown)" }
